contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 tokenId, uint256 weight, uint256 baseTokenAmount)
        public
        payable
    {
        require(weight > 0);
        require(baseTokenAmount > 0);
        require(address(this).balance >= baseTokenAmount);

        uint256[] memory ids = new uint256[](1);
        ids[0] = tokenId;
        uint256[] memory weights = new uint256[](1);
        weights[0] = weight;
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.buyQuote(weight);

        uint256 balanceBefore = address(this).balance;

        (uint256 paid, uint256 fee, uint256 protocolFee) =
            c.buy{value: baseTokenAmount}(ids, weights, proof);

        assert(
            paid == netInputAmount + feeAmount + protocolFeeAmount &&
            fee == feeAmount &&
            protocolFee == protocolFeeAmount &&
            balanceBefore - address(this).balance ==
                netInputAmount + feeAmount + protocolFeeAmount
        );
    }
}

