contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties,
        uint256 buyAmount
    ) public payable {
        require(buyAmount > 0);

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        uint256[] memory emptyIds = new uint256[](0);
        uint256[] memory emptyWeights = new uint256[](0);
        C.MerkleMultiProof memory emptyProof;
        emptyProof.proof = new bytes32[](0);
        emptyProof.flags = new bool[](0);

        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.buy{value: buyAmount}(emptyIds, emptyWeights, emptyProof) returns (
            uint256 netInput,
            uint256 fee,
            uint256 protocolFee
        ) {
            netInputAmount = netInput;
            feeAmount = fee;
            protocolFeeAmount = protocolFee;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint128 afterVirtualBase = c.virtualBaseTokenReserves();
            uint256 kept = netInputAmount - feeAmount - protocolFeeAmount;
            assert(uint256(afterVirtualBase) - uint256(beforeVirtualBase) == kept);
        } else {
            assert(c.virtualBaseTokenReserves() == beforeVirtualBase);
        }
    }
}

